def parse_help_groups(help_text):
    lines = help_text.split("\n")
    groups = []
    for line in lines:
        if not line.startswith("  "):
            continue
        stripped = line[2:]
        if not stripped.startswith("-"):
            continue
        if "<" in stripped:
            idx = stripped.find("<")
            flags_part = stripped[:idx].strip()
            rest = stripped[idx:]
            m = re.search(r'  ', rest)
            metavar = rest[:m.start()].strip() if m else rest.strip()
            takes_value = True
        else:
            m = re.search(r'  ', stripped)
            flags_part = stripped[:m.start()].strip() if m else stripped.strip()
            takes_value = False
            metavar = None
        flags = []
        for part in flags_part.split(","):
            part=part.strip()
            if not part:
                continue
            for p in part.split():
                p=p.strip()
                if p.startswith("-"):
                    flags.append(p)
        if flags:
            groups.append((flags, takes_value, metavar))
    return groups

def parse_positionals(help_text, js):
    lines = help_text.split("\n")
    pos = []
    in_pos = False
    for i, line in enumerate(lines):
        if "Positional arguments:" in line:
            in_pos = True
            continue
        if in_pos:
            if line and not line.startswith(" ") and not line.startswith("\t"):
                if line.strip()=="":
                    j=i+1
                    while j<len(lines) and lines[j].strip()=="":
                        j+=1
                    if j<len(lines) and ("Options:" in lines[j] or "For more" in lines[j]):
                        break
                    else:
                        continue
                else:
                    break
            if line.strip()=="":
                continue
            if not line.startswith("  "):
                continue
            stripped = line[2:]
            if not stripped.startswith("-"):
                continue
            if "<" in stripped:
                idx = stripped.find("<")
                flags_part = stripped[:idx].strip()
                rest = stripped[idx:]
                m = re.search(r'  ', rest)
                metavar_full = rest[:m.start()].strip() if m else rest.strip()
                mm = re.search(r'<([^>]+)>', metavar_full)
                if mm:
                    meta_name = mm.group(1)
                    is_repeated = "..." in metavar_full
                else:
                    meta_name = metavar_full
                    is_repeated = False
                flags = []
                for part in flags_part.split(","):
                    part=part.strip()
                    for p in part.split():
                        if p.startswith("-"):
                            flags.append(p)
                desc = rest[m.end():] if m else ""
                required = "[required]" in line or "[required]" in desc
                may_repeat = "[may be repeated]" in line
                pos.append({"flags": flags, "metavar": meta_name, "metavar_full": metavar_full, "required": required, "repeated": is_repeated or may_repeat, "line": line})
    return pos

def build_spec(path):
    key = tuple(path)
    if key in SPEC_CACHE:
        return SPEC_CACHE[key]
    import dispatch, spec_parser
    help_text = dispatch.get_help_text(path)
    name = dispatch.json_name_for_path(path)
    js = None
    if name:
        p = os.path.join(HELP_DIR, name+".stdout")
        try:
            with open(p) as f:
                js = json.load(f)
        except:
            js=None
    flag_map = spec_parser.parse_help_flags(help_text)
    arg_specs = {}
    if js:
        for k in ["input_arguments","output_arguments","input_output_arguments"]:
            for a in js.get(k,[]):
                arg_specs[a["name"]] = a
    groups = parse_help_groups(help_text)
    flag_to_arg = {}
    for flags, takes_value, metavar in groups:
        matched=None
        for fl in flags:
            if fl.startswith("--"):
                n=fl[2:]
                if n in arg_specs:
                    matched=n
                    break
        if matched:
            for fl in flags:
                flag_to_arg[fl]=matched
        else:
            for fl in flags:
                if fl in ["-h","--help"]:
                    flag_to_arg[fl]="__help"
                elif fl=="--json-usage":
                    flag_to_arg[fl]="__json"
                elif fl=="--config":
                    flag_to_arg[fl]="__config"
                elif fl=="--drivers":
                    flag_to_arg[fl]="__drivers"
                else:
                    flag_to_arg[fl]=fl.lstrip("-")
    for fl in flag_map:
        if fl not in flag_to_arg:
            if fl.startswith("--") and fl[2:] in arg_specs:
                flag_to_arg[fl]=fl[2:]
            elif fl in ["-h","--help"]:
                flag_to_arg[fl]="__help"
            elif fl=="--json-usage":
                flag_to_arg[fl]="__json"
            elif fl=="--config":
                flag_to_arg[fl]="__config"
            else:
                found=None
                for gflags,_,_ in groups:
                    if fl in gflags:
                        for gf in gflags:
                            if gf.startswith("--") and gf[2:] in arg_specs:
                                found=gf[2:]
                                break
                        if found:
                            break
                flag_to_arg[fl]=found if found else fl.lstrip("-")
    spec={"flag_map":flag_map,"arg_specs":arg_specs,"flag_to_arg":flag_to_arg,"groups":groups,"help_text":help_text,"json":js}
    spec["positionals"]=parse_positionals(help_text, js)
    SPEC_CACHE[key]=spec
    return spec
