def parse_geojson(path):
    """Parse GeoJSON file, return dict with layer info"""
    with open(path, "r", encoding="utf-8") as f:
        txt = f.read()
    j = json.loads(txt)
    # Determine layer name: from "name" field or filename without ext?
    # For test.geojson, name is "test" or from filename? test.geojson has no "name" field (original test file has no name, just features), but info shows Layer name: test (from filename). For out.geojson with "name":"test", info shows test. For new.geojson with "name":"new", shows new. So layer name is "name" if present, else basename without ext.
    # Check: what about single Feature (not FeatureCollection)? Then layer name? Probably filename? And geometry type from feature?
    # Handle different types:
    # - FeatureCollection with features: layer with features
    # - Single Feature: layer with 1 feature?
    # - Single geometry (Point etc.): layer with 1 feature with that geometry and no properties?
    # - Empty FeatureCollection: 0 features, Unknown geometry
    layer_name = j.get("name") if isinstance(j, dict) and "name" in j else os.path.splitext(os.path.basename(path))[0]
    # CRS: from "crs" field? If missing, default 4326. If present with name containing EPSG::3857 => 3857, if CRS84 => 4326.
    crs_str = "EPSG:4326"  # default
    if isinstance(j, dict) and "crs" in j:
